s/${competition.id}`" class="glass card card-hover competition-card"><div class="competition-icon"><Trophy :size="26"/></div><span class="badge green">{{ competition.status }}</span><h3>{{ competition.name }}</h3><p>{{ competition.series_name }} · {{ competition.season_name }}</p><div class="competition-meta"><span>{{ competition.format_type }}</span><ArrowRight :size="17"/></div></RouterLink></div><section class="section-title section-gap"><div><span class="eyebrow">Lịch sử vinh quang</span><h2>Nhà vô địch gần nhất</h2></div></section><div class="champions"><article v-for="champion in data.champions" :key="champion.id" class="glass champion-card"><Crown class="crown" :size="28"/><EntityAvatar :src="champion.logo_url" :name="champion.club_name" :size="64"/><div><small>{{ champion.competition_name }} · {{ champion.season_name }}</small><h3>{{ champion.club_name }}</h3><p>Vô địch với hệ số {{ champion.applied_coefficient || '—' }}</p></div></article></div></template></div></div></template>
